for(const m of PALADIN_MOVES)m.approvedExpansion362=true;
export const PALADIN_IDS=PALADIN_SPECIES.filter(s=>s.legendaryRoamer).map(s=>s.id);
export const VERDANTYR_ID='425';
export function installPaladins(data){
 if(data.species.some(s=>s.approvedPaladin))return;
 data.species.push(...PALADIN_SPECIES);data.moves.push(...PALADIN_MOVES);
 for(const [i,s]of PALADIN_SPECIES.entries()){
  const kind=s.growth_percent.attack>=s.growth_percent.sp_attack?'PHYSICAL':'SPECIAL';s.moveset_identity={version:1,style:s.role,plan:'Use '+s.ability_names.primary+' with '+PALADIN_MOVES[i].name+'; preserve the species’ distinctive offence and defensive weaknesses.',kind:/tank|healer|vanguard/.test(s.role)?'guard':s.growth_percent.speed>=80?'speed':'power',category:kind};
  const pool=data.moves.filter(m=>m.power>0&&!m.signature_owner_family&&m.category===kind&&s.types.includes(m.type_id));
  const pick=(lo,hi,type=null)=>pool.filter(m=>m.power>=lo&&m.power<=hi&&(!type||m.type_id===type)).sort((a,b)=>a.power-b.power||a.id-b.id)[0];
  const weak=pick(35,50)||pick(35,65),medium=pick(55,75),strong=pick(75,95);if(!weak||!medium||!strong)throw Error('Missing STAB learnset for '+s.name);
  const support=/tank|healer|vanguard/.test(s.role)?'defence':kind==='PHYSICAL'?'attack':'sp_attack';const guard=data.moves.find(m=>m.category==='STATUS'&&m.target==='SELF'&&m.effects?.some(e=>e.effect_id==='stat_stage'&&(e.stats||[e.stat]).includes(support)));
  const preferred=['GROUND','ROCK','ROCK','PSYCHIC','FIGHTING','DARK','FAIRY','GROUND','GHOST','FIGHTING','GRASS','ICE','STEEL','GRASS'][i];const cover=data.moves.filter(m=>m.power>=40&&m.power<=65&&m.category===kind&&!m.signature_owner_family&&!s.types.includes(m.type_id)&&m.type_id!=='NORMAL').sort((a,b)=>Number(b.type_id===preferred)-Number(a.type_id===preferred)||a.id-b.id)[0];
  const signature=PALADIN_MOVES[i],schedule=[[1,weak.id],[6,guard?.id||weak.id],[12,medium.id],[16,cover.id],[26,strong.id],[s.legendaryRoamer?32:30,signature.id]];
  if(s.id===VERDANTYR_ID)schedule.push([22,128],[24,337],[38,346]);
  const seen=new Map();for(const[level,id]of schedule)seen.set(id,Math.min(level,seen.get(id)??200));
  const rows=[...seen].map(([move_id,level])=>({species_id:s.id,move_id,level,name:data.moves.find(m=>m.id===move_id).name,method:'LEVEL_UP',expansion:true,identity:true,identity_core:true,approvedPaladin:true})).sort((a,b)=>a.level-b.level);
  data.learnsets.push(...rows);data.authoredLearnsets?.push(...rows.map(r=>({...r})));data.assets.push({id:s.id,runtime:'assets/'+s.id+'.webp',source:'art-source/paladin/'+s.id+'.webp'});
 }
}

for(const h of PALADIN_HONOURS){const s=PALADIN_SPECIES.find(s=>s.id===h.id);if(s){s.mark_of_honour=h.mark;s.stewardship=h.duty;s.catalogue_entry=h.mark+': '+h.duty;}}
